parameters.jsCode:
// ── Parse Claude's response and extract summary + category ──

const claudeResponse = $input.item.json;

// Claude returns content as an array of content blocks
const rawText = claudeResponse.content[0].text.trim();

let parsed;
try {
  // Happy path — Claude returned clean JSON
  parsed = JSON.parse(rawText);
} catch (e) {
  // Fallback — strip markdown code fences if Claude added them
  const jsonMatch = rawText.match(/\{[\s\S]*?\}/);
  if (!jsonMatch) {
    throw new Error(`Claude did not return valid JSON. Raw response: ${rawText}`);
  }
  parsed = JSON.parse(jsonMatch[0]);
}

// Validate expected fields
if (!parsed.summary || !parsed.category) {
  throw new Error(`Missing fields in Claude response: ${JSON.stringify(parsed)}`);
}

// Pull row_number from the trigger so we can update the right row
const triggerData = $('Google Sheets Trigger').item.json;

return [
  {
    json: {
      summary:    parsed.summary,
      category:   parsed.category,
      row_number: triggerData.row_number,
      input_text: triggerData.Input
    }
  }
];
